&lt;span id=&#34;cb3-42&#34;&gt;&lt;a href=&#34;#cb3-42&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;            &lt;span class=&#34;op&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb3-43&#34;&gt;&lt;a href=&#34;#cb3-43&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;            la &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;2&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;sR &lt;span class=&#34;op&#34;&gt;-&lt;/span&gt; sL&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;-&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;R&lt;span class=&#34;op&#34;&gt;.&lt;/span&gt;top&lt;span class=&#34;op&#34;&gt;()&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;-&lt;/span&gt; L&lt;span class=&#34;op&#34;&gt;.&lt;/span&gt;top&lt;span class=&#34;op&#34;&gt;());&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb3-44&#34;&gt;&lt;a href=&#34;#cb3-44&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        &lt;span class=&#34;op&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb3-45&#34;&gt;&lt;a href=&#34;#cb3-45&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        res &lt;span class=&#34;op&#34;&gt;^=&lt;/span&gt; la&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb3-46&#34;&gt;&lt;a href=&#34;#cb3-46&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;op&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb3-47&#34;&gt;&lt;a href=&#34;#cb3-47&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    printf&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;st&#34;&gt;&amp;quot;&lt;/span&gt;&lt;span class=&#34;sc&#34;&gt;%lld\n&lt;/span&gt;&lt;span class=&#34;st&#34;&gt;&amp;quot;&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; res&lt;span class=&#34;op&#34;&gt;);&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb3-48&#34;&gt;&lt;a href=&#34;#cb3-48&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;bu&#34;&gt;std::&lt;/span&gt;cerr &lt;span class=&#34;op&#34;&gt;&amp;lt;&amp;lt;&lt;/span&gt; &lt;span class=&#34;bu&#34;&gt;std::&lt;/span&gt;fixed &lt;span class=&#34;op&#34;&gt;&amp;lt;&amp;lt;&lt;/span&gt; &lt;span class=&#34;bu&#34;&gt;std::&lt;/span&gt;setprecision&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;dv&#34;&gt;6&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;lt;&amp;lt;&lt;/span&gt; &lt;span class=&#34;bu&#34;&gt;std::&lt;/span&gt;chrono::duration&lt;span class=&#34;op&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;dt&#34;&gt;double&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;&amp;gt;(&lt;/span&gt;&lt;span class=&#34;bu&#34;&gt;std::&lt;/span&gt;chrono::steady_clock::now&lt;span class=&#34;op&#34;&gt;()&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;-&lt;/span&gt; stime&lt;span class=&#34;op&#34;&gt;).&lt;/span&gt;count&lt;span class=&#34;op&#34;&gt;()&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;lt;&amp;lt;&lt;/span&gt; &lt;span class=&#34;st&#34;&gt;&amp;quot;s &lt;/span&gt;&lt;span class=&#34;sc&#34;&gt;\n&lt;/span&gt;&lt;span class=&#34;st&#34;&gt;&amp;quot;&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb3-49&#34;&gt;&lt;a href=&#34;#cb3-49&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;cf&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb3-50&#34;&gt;&lt;a href=&#34;#cb3-50&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;&lt;span class=&#34;op&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;
&lt;/details&gt;
&lt;hr /&gt;
&lt;h2 id=&#34;c.-整式比较-qoj10506.-waga&#34;&gt;C. 整式比较 / qoj#10506. Waga&lt;/h2&gt;
&lt;p&gt;&lt;a href=&#34;https://www.becoder.com.cn/contest/6685/problem/3&#34;
class=&#34;uri&#34;&gt;https://www.becoder.com.cn/contest/6685/problem/3&lt;/a&gt; / &lt;a
href=&#34;https://qoj.ac/problem/10506&#34;
class=&#34;uri&#34;&gt;https://qoj.ac/problem/10506&lt;/a&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;给定 &lt;span class=&#34;math inline&#34;&gt;\(a_{1\cdots
n}\)&lt;/span&gt;，和一个称，如下操作称为一次『称重』：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;选中 &lt;span class=&#34;math inline&#34;&gt;\(a\)&lt;/span&gt;
的一个子集，输入给称。记它们的和为 &lt;span
class=&#34;math inline&#34;&gt;\(s\)&lt;/span&gt;，那么称会返回 &lt;span
class=&#34;math inline&#34;&gt;\(\min(k,\left\lfloor \dfrac sc
\right\rfloor)\)&lt;/span&gt;，其中，&lt;span class=&#34;math inline&#34;&gt;\(c\)&lt;/span&gt;
为给定常数。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;现在对于每个无序对 &lt;span class=&#34;math inline&#34;&gt;\((i,j)\)&lt;/span&gt;（&lt;span
class=&#34;math inline&#34;&gt;\(i\ne j\)&lt;/span&gt;），你需要判断：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;在已知 &lt;span class=&#34;math inline&#34;&gt;\(a\)&lt;/span&gt; 中除 &lt;span
class=&#34;math inline&#34;&gt;\(a_i,a_j\)&lt;/span&gt; 外所有元素值，且 &lt;span
class=&#34;math inline&#34;&gt;\(a_i,a_j\)&lt;/span&gt;
数值未知的前提下，是否可以通过若干次称重确定 &lt;span
class=&#34;math inline&#34;&gt;\(a_i,a_j\)&lt;/span&gt; 的大小关系。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&#34;math inline&#34;&gt;\(n,c\le 8000,k\le 10^5,1\le a_i&amp;lt;
kc\)&lt;/span&gt;。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;&lt;p&gt;显然，&lt;span class=&#34;math inline&#34;&gt;\(a_i\)&lt;/span&gt; 和 &lt;span
class=&#34;math inline&#34;&gt;\(a_j\)&lt;/span&gt; 能区分，当且仅当 &lt;span
class=&#34;math inline&#34;&gt;\(\left\lfloor\dfrac {a_i}c\right\rfloor\ne
\left\lfloor\dfrac
{a_j}c\right\rfloor\)&lt;/span&gt;，或者存在一个其他元素的子集 &lt;span
class=&#34;math inline&#34;&gt;\(s\)&lt;/span&gt;，使得 &lt;span
class=&#34;math inline&#34;&gt;\(\left\lfloor\dfrac {a_i+s}c\right\rfloor\ne
\left\lfloor\dfrac {a_j + s}c\right\rfloor\)&lt;/span&gt;。&lt;/p&gt;
&lt;p&gt;反过来，如果 &lt;span class=&#34;math inline&#34;&gt;\(a_i\)&lt;/span&gt; 和 &lt;span
class=&#34;math inline&#34;&gt;\(a_j\)&lt;/span&gt; 不能区分，一个前提是 &lt;span
class=&#34;math inline&#34;&gt;\(\left\lfloor\dfrac {a_i}c\right\rfloor
=\left\lfloor\dfrac {a_j}c\right\rfloor\)&lt;/span&gt;。&lt;/p&gt;&lt;/li&gt;
&lt;li&gt;&lt;p&gt;下意识猜要排序，排序后打表发现使 &lt;span
class=&#34;math inline&#34;&gt;\(i\)&lt;/span&gt; 不合法的 &lt;span
class=&#34;math inline&#34;&gt;\(j\)&lt;/span&gt; 总是连续的。&lt;/p&gt;
&lt;details&gt;
&lt;summary&gt;
&lt;p&gt;证明&lt;/p&gt;
&lt;/summary&gt;
&lt;ol type=&#34;1&#34;&gt;
&lt;li&gt;&lt;p&gt;需要证：对于 &lt;span class=&#34;math inline&#34;&gt;\(x&amp;lt;y&amp;lt;z\)&lt;/span&gt;，若
&lt;span class=&#34;math inline&#34;&gt;\(x,y\)&lt;/span&gt; 不可区分，且 &lt;span
class=&#34;math inline&#34;&gt;\(y,z\)&lt;/span&gt; 不可区分，那么 &lt;span
class=&#34;math inline&#34;&gt;\(x,z\)&lt;/span&gt; 不可区分。&lt;/p&gt;
&lt;p&gt;记 &lt;span class=&#34;math inline&#34;&gt;\(\left\lfloor\dfrac
{x}c\right\rfloor=\left\lfloor\dfrac
{y}c\right\rfloor=\left\lfloor\dfrac
{z}c\right\rfloor=w\)&lt;/span&gt;，不存在 &lt;span class=&#34;math inline&#34;&gt;\(s\le
c\cdot (k-w)\)&lt;/span&gt;，使得 &lt;span class=&#34;math inline&#34;&gt;\(y\)&lt;/span&gt;
可以进位但 &lt;span class=&#34;math inline&#34;&gt;\(x\)&lt;/span&gt; 不可，也不存在这样的
&lt;span class=&#34;math inline&#34;&gt;\(s\)&lt;/span&gt; 使得 &lt;span
class=&#34;math inline&#34;&gt;\(z\)&lt;/span&gt; 可以进位但 &lt;span
class=&#34;math inline&#34;&gt;\(y\)&lt;/span&gt; 不可。&lt;/p&gt;
&lt;p&gt;合并不等式容易得到不存在这样的 &lt;span class=&#34;math inline&#34;&gt;\(x\)&lt;/span&gt;
使得 &lt;span class=&#34;math inline&#34;&gt;\(z\)&lt;/span&gt; 可以进位但 &lt;span
class=&#34;math inline&#34;&gt;\(x\)&lt;/span&gt; 不可。&lt;/p&gt;&lt;/li&gt;
&lt;li&gt;&lt;p&gt;需要证：对于 &lt;span class=&#34;math inline&#34;&gt;\(x&amp;lt;y&amp;lt;z\)&lt;/span&gt;，若
&lt;span class=&#34;math inline&#34;&gt;\(x,y\)&lt;/span&gt; 可区分或 &lt;span
class=&#34;math inline&#34;&gt;\(y,z\)&lt;/span&gt; 可区分，则 &lt;span
class=&#34;math inline&#34;&gt;\(x,z\)&lt;/span&gt; 可区分。&lt;/p&gt;
&lt;p&gt;调整法易得。&lt;/p&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;/details&gt;&lt;/li&gt;
&lt;li&gt;&lt;p&gt;故发现只需要讨论相邻两个元素是否可区分。需要知道所有可能的子集和用于
check，可以用分治预处理『只有某相邻两个元素不选』时的前后缀背包数组（到达某个余数时需要的最小整倍数），就可以
&lt;span class=&#34;math inline&#34;&gt;\(O(nc\log n)\)&lt;/span&gt; 解决问题。&lt;/p&gt;
&lt;p&gt;考虑在做什么：删点在 &lt;span
class=&#34;math inline&#34;&gt;\([l,mid]\)&lt;/span&gt;，那么 &lt;span
class=&#34;math inline&#34;&gt;\([mid+1,r]\)&lt;/span&gt; 的 DP 数组不会受到影响；删点在
&lt;span class=&#34;math inline&#34;&gt;\([mid + 1, r]\)&lt;/span&gt;，那么 &lt;span
class=&#34;math inline&#34;&gt;\([l,mid]\)&lt;/span&gt; 的 DP
数组不会受到影响。背包的物品是无顺序的，所以有正确性。&lt;/p&gt;
&lt;p&gt;也就是说大部分信息是可继承的。&lt;em&gt;为什么题解管这个叫
CDQ？是因为普通分治总会被叫 CDQ 吗？&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;做一个类似 01 背包滚动数组的东西，维护每个点前 /
后可以凑出来的背包值，在最后下传到单点时统计答案即可。&lt;/p&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;details&gt;
&lt;p&gt;相邻两个的处理略显烧脑，但意外地简洁。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;&amp;gt;=&lt;/code&gt; 不要写成除，不然会慢成唐诗&lt;/p&gt;
&lt;div class=&#34;sourceCode&#34; id=&#34;cb4&#34;&gt;&lt;pre
class=&#34;sourceCode cpp&#34;&gt;&lt;code class=&#34;sourceCode cpp&#34;&gt;&lt;span id=&#34;cb4-1&#34;&gt;&lt;a href=&#34;#cb4-1&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;&lt;span class=&#34;pp&#34;&gt;#include &lt;/span&gt;&lt;span class=&#34;im&#34;&gt;&amp;lt;bits/stdc++.h&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-2&#34;&gt;&lt;a href=&#34;#cb4-2&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;&lt;span class=&#34;at&#34;&gt;const&lt;/span&gt; &lt;span class=&#34;dt&#34;&gt;int&lt;/span&gt; maxn &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;fl&#34;&gt;8e3&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;5&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-3&#34;&gt;&lt;a href=&#34;#cb4-3&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;&lt;span class=&#34;dt&#34;&gt;char&lt;/span&gt; nec&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;dt&#34;&gt;void&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-4&#34;&gt;&lt;a href=&#34;#cb4-4&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;at&#34;&gt;static&lt;/span&gt; &lt;span class=&#34;dt&#34;&gt;char&lt;/span&gt; buf&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;lt;&amp;lt;&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;20&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;],&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;*&lt;/span&gt;p &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; buf&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;*&lt;/span&gt;e &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; buf&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-5&#34;&gt;&lt;a href=&#34;#cb4-5&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;cf&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;p &lt;span class=&#34;op&#34;&gt;==&lt;/span&gt; e&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-6&#34;&gt;&lt;a href=&#34;#cb4-6&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        e &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; buf &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; fread&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;buf&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;lt;&amp;lt;&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;20&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; stdin&lt;span class=&#34;op&#34;&gt;);&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-7&#34;&gt;&lt;a href=&#34;#cb4-7&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        p &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; buf&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-8&#34;&gt;&lt;a href=&#34;#cb4-8&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;op&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-9&#34;&gt;&lt;a href=&#34;#cb4-9&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;cf&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;*&lt;/span&gt;p&lt;span class=&#34;op&#34;&gt;++;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-10&#34;&gt;&lt;a href=&#34;#cb4-10&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;&lt;span class=&#34;op&#34;&gt;&amp;#125;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-11&#34;&gt;&lt;a href=&#34;#cb4-11&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;&lt;span class=&#34;dt&#34;&gt;int&lt;/span&gt; read&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;dt&#34;&gt;void&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb4-12&#34;&gt;&lt;a href=&#34;#cb4-12&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;kw&#34;&gt;auto&lt;/span&gt; x &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;bu&#34;&gt;ll&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
