&lt;span id=&#34;cb6-9&#34;&gt;&lt;a href=&#34;#cb6-9&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;cf&#34;&gt;return&lt;/span&gt; sqrt&lt;span class=&#34;op&#34;&gt;((&lt;/span&gt;x1 &lt;span class=&#34;op&#34;&gt;-&lt;/span&gt; x2&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;x1 &lt;span class=&#34;op&#34;&gt;-&lt;/span&gt; x2&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt;&lt;/span&gt;
